INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('qvs29nh50v8toag0dfk3qvs29njtuu1x', '2025-Q4', 'Dez/2025', '2025-12-16T13:52'::timestamptz, 'Saulo Lourenço Siqueira', 'saulo lourenco siqueira', 'PHARUS', 'Tales Salinas Rozo', 9.0, 'Promotor', 10.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Tenho clareza e estou executando com consistência', NULL, NULL, 'Gosto muito das sugestões, de fato elas fazem muito sentido, porém acho que para investidores novos, principalmente, pouco familiarizados com investimentos no mercado real, a gente fica ainda muito inseguro durante a implementação das estratégias. Talvez maiores informações sobre as empresas que funcionam como mediadoras da implementação, histórico, reputação, confiança. Algo nesse sentido nos deixaria mais seguros', 'Começar a ver resultado a partir desse segundo ano de implementação', 'Gosto muito do acompanhamento mas meu nível de insegurança está desconfortavelmente alto. Estou inseguro com a estratégia de autoconstrucao pois o grupo é muito grande e não consigo ver como lances fixos podem me dar o retorno estatístico conforme previsto uma vez que o grupo está bastante agressivo. Também estou inseguro com a renda sintética pois fiz o aporte há 14 dias e ainda não tenho a confirmação oficial da liquidação. Estou inseguro pois confio em vocês, mas por tabela preciso confiar nas empresas indicadas (Servopa, mova, vitacon) e são dadas poucas informações de confiabilidade dessas empresas o que gera insegurança na implementação das estratégias', NULL, NULL, 'legado', 'NPS_Q4_2025_ENVIADO_DEZEMBRO.xlsx', 'pharus 2', 'qvs29nh50v8toag0dfk3qvs29njtuu1x', 'aba PHARUS da planilha', 'MARÇO') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
