INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('rjjv8dkwm6dev1krjps3bwjccymhluln', '2025-Q4', 'Dez/2025', '2025-12-16T15:11'::timestamptz, 'Heitor Parenti Junior', 'heitor parenti junior', 'PHARUS', NULL, 9.0, 'Promotor', 9.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Tenho clareza e estou executando com consistência', NULL, NULL, NULL, 'Se eu não tiver o retorno minimamente do investido no programa Pharus esse ano, minha tendência é não continuar com o programa. Para continuar, o custo do programa teria que se pagar anualmente + a geracao de retorno acima do que é praticado no mercado comum. A curva do 4o caminho tem que se materializar, considerando o custo do programa também.', 'A assessora Camila da Avant (suporte a consórcio Porto) deixou muito a desejar em todas as interações…  respostas sempre com atraso, vagas e suporte moroso.
